      'Когда вы задаёте тему и не передаёте базовые ссылки. Если ссылки указаны, агент сначала работает по ним и не ищет тему заново в интернете.',
    'agentFaq.goal.question': 'Что писать в поле «Тема / цель»?',
    'agentFaq.goal.answer':
      'Только саму область поиска: тему, нишу, регион, аудиторию или нужный ракурс. Например: локальные новости Новосибирска, обновления для продавцов на маркетплейсах, идеи для путешествий.',
    'agentFaq.instructions.question': 'Что писать в поле «Инструкции к черновику»?',
    'agentFaq.instructions.answer':
      'Правила оформления результата: длина, тон, структура, нужны ли картинки и какие. Например: короткий пост без служебных разделов, спокойный тон, 3–5 фактов, при наличии добавь подходящие публичные изображения.',
    'agentFaq.seeds.question': 'Что такое «Базовые ссылки»?',
    'agentFaq.seeds.answer':
      'Это ссылки, от которых агент должен отталкиваться. Они полезны, когда вы уже знаете надёжные источники и хотите, чтобы агент работал по ним, а не искал всё с нуля.',
    'agentFaq.auto.question': 'Что делает режим «Авто»?',
    'agentFaq.auto.answer':
      'Агент сам проводит безопасные варианты дальше по workflow. Если источников недостаточно, есть конфликт или не хватает картинок при явном запросе на изображения, результат уходит на согласование вместо автоматического продвижения.',
    'agentFaq.reviewFallback.question': 'Почему результат может уйти в согласование, а не создаться сразу?',
    'agentFaq.reviewFallback.answer':
      'Обычно это происходит, когда у кандидата не хватает качественных источников, найден только один источник, обнаружены конфликты между источниками, повторяется уже недавний угол темы или не найдены изображения при явном запросе на картинки.',
    'agentFaq.images.question': 'Почему в посте может не быть картинки?',
    'agentFaq.images.answer':
      'Картинки берутся из найденных или переданных источников. Если в источниках нет подходящих публичных изображений, агент не должен выдумывать их. В таком случае результат либо создаётся без картинки, либо уходит на согласование — в зависимости от режима.',
    'agentFaq.results.question': 'Где смотреть результат работы Агента поиска?',
    'agentFaq.results.answer':
      'Статус запуска виден в карточке запуска. Сами кандидаты и спорные варианты удобнее смотреть в очереди согласования. Уже созданные черновики и посты находятся в разделе «Контент».',
    'agentFaq.multipleTasks.question': 'Можно ли завести несколько задач поиска одновременно?',
    'agentFaq.multipleTasks.answer':
      'Да. Каждая задача поиска — отдельная сущность со своей темой, инструкциями, режимом работы и расписанием. Их можно запускать вручную, останавливать, возобновлять и удалять отдельно друг от друга.',

