    'home.faq.eyebrow': 'Questions',
    'home.faq.title': 'The important bits, briefly',
    'home.faq.who.question': 'Who is Postbridge for?',
    "home.faq.who.answer": "For creators, brands, editorial teams, and agencies that need to create posts, images, and short videos, then publish them to their channels.",
    'home.faq.agents.question': 'What do agents do?',
    "home.faq.agents.answer": "They help find topics and sources, write and edit posts. The video studio assistant works with storyboards, scenes, voiceovers, and production schedules.",
    'home.faq.destinations.question': 'Where does content go next?',
    'home.faq.destinations.answer':
      'To connected channels and bridges: Telegram, MAX, VK, RSS, and the built-in Postbridge source. A common flow is to prepare material with an agent and distribute it across platforms.',
    'home.faq.destinations.answer.io':
      'To connected channels and bridges: Telegram, LinkedIn, X, Bluesky, Mastodon, and RSS. A common flow is to prepare material with an agent and distribute it across platforms.',
