    'agentFaq.publicTitle': 'AI agents FAQ',
    'agentFaq.publicSubtitle': 'Short answers about how agents find topics, prepare publications, and send results into Postbridge.',
    'agentFaq.title': 'Agents FAQ',
    'agentFaq.subtitle': 'Short answers about how Topic scout and Editor agent work',
    'agentFaq.difference.question': 'How is Topic scout different from Editor agent?',
    'agentFaq.difference.answer':
      'Topic scout searches for topics, sources, and publication candidates. Editor agent works with a specific post: it helps rewrite, shorten, structure, and polish a draft.',
    'agentFaq.webSearch.question': 'When does Topic scout use web search?',
    'agentFaq.webSearch.answer':
      'When you provide a topic and do not provide seed links. If links are provided, the agent starts from them and does not search the web from scratch.',
    'agentFaq.goal.question': 'What should I put in "Topic / goal"?',
    'agentFaq.goal.answer':
      'Only the search area: topic, niche, region, audience, or angle. For example: local Novosibirsk news, updates for marketplace sellers, or travel ideas.',
    'agentFaq.instructions.question': 'What should I put in "Draft instructions"?',
    'agentFaq.instructions.answer':
      'Rules for the result: length, tone, structure, whether images are needed, and what kind. For example: short post without service sections, calm tone, 3-5 facts, add suitable public images when available.',
    'agentFaq.seeds.question': 'What are seed links?',
    'agentFaq.seeds.answer':
      'Links the agent should use as starting points. They are useful when you already know reliable sources and want the agent to work from them instead of searching from zero.',
    'agentFaq.auto.question': 'What does Auto mode do?',
    'agentFaq.auto.answer':
      'The agent advances safe variants through the workflow. If sources are insufficient, conflicts appear, or images are missing when explicitly requested, the result goes to review instead of automatic promotion.',
    'agentFaq.reviewFallback.question': 'Why can a result go to review instead of being created immediately?',
    'agentFaq.reviewFallback.answer':
      'Usually because the candidate lacks strong sources, has only one source, contains source conflicts, repeats a recent angle, or has no images despite an explicit image request.',
    'agentFaq.images.question': 'Why might a post have no image?',
    'agentFaq.images.answer':
      'Images come from found or provided sources. If sources do not contain suitable public images, the agent should not invent them. The result is either created without an image or sent to review, depending on mode.',
    'agentFaq.results.question': 'Where can I see Topic scout results?',
    'agentFaq.results.answer':
      'Run status is visible in the run card. Candidates and disputed variants are easier to inspect in the review queue. Created drafts and posts live in Content.',
    'agentFaq.multipleTasks.question': 'Can I create several scout tasks at once?',
    'agentFaq.multipleTasks.answer':
      'Yes. Each scout task is its own entity with a topic, instructions, mode, and schedule. You can run, pause, resume, and delete them separately.',

